(function(root,factory){const data=factory();if(typeof module==='object'&&module.exports)module.exports=data;root.MO_STORIES=data;})(typeof window!=='undefined'?window:globalThis,function(){return [{"id":"skarmbild","subject":"sv","genre":"Berättelse","title":"Skärmbilden i gruppchatten","lead":"En överraskning, ett löfte och ett missförstånd.","levels":[{"level":1,"text":["Mira och Leila skulle ordna klassens avslutningskväll. Förra veckan hade Mira råkat snubbla när de spelade in en film. Alla skrattade, också Mira. Men när hon såg klippet efteråt ville hon inte att fler skulle se det. ”Jag lovar att inte visa klippet”, sa Leila.","På torsdagen skickade någon en skärmbild till Mira. Där stod: ”Mira kommer bli helt chockad när videon visas!” Mira blev orolig. Hon skrev till Leila men fick inget svar. När Leila frågade vad som var fel sa Mira bara: ”Du vet.”","På kvällen visades en film med bilder på allt Mira gjort för klassen. Den pinsamma filmen fanns inte med. Leila hade ordnat en överraskning. Mira blev glad, men också ledsen över att de inte hade pratat tidigare."]},{"level":2,"text":["Mira hade hjälpt till med klassens avslutningskväll i flera veckor. Hon valde musik, gjorde affischer och redigerade filmklipp. Under en repetition snubblade hon över en stol. Hon skrattade tillsammans med de andra, men hemma tyckte hon att klippet såg pinsamt ut. ”Jag lovar att inte visa klippet”, sa Leila och lade mobilen åt sidan.","Dagen före kvällen skickade en elev en skärmbild till Mira. I en annan gruppchatt stod det: ”Mira kommer bli helt chockad när videon visas!” Mira läste meningen gång på gång. Hon tänkte direkt på fallet. Leila svarade inte när Mira skickade två meddelanden. Nästa dag försökte Leila prata, men Mira svarade: ”Du vet.” Hon berättade inte vad hon misstänkte.","På kvällen spelades en hyllningsfilm upp. Där syntes Mira när hon hjälpte klasskamraterna och fick andra att skratta. Den pinsamma filmen fanns inte med. Leila hade velat visa hur mycket Mira betytt för klassen. Efteråt sa Leila att hon hade sett meddelandena sent. Mira förstod missförståndet. Men hon funderade också på varför hon hade varit så säker utan att fråga."]},{"level":3,"text":["Mira var den som alltid verkade ha kontroll över klassens projekt. När andra glömde tider eller tappade bort filer löste hon problemen, ofta utan att någon märkte det. Därför kändes det märkligt att vara nervös inför avslutningskvällen som hon själv hjälpt till att skapa.","Vid en repetition hade hon snubblat framför kameran. Skrattet var först befriande, men när klippet spelades upp i mobilen kände hon sig plötsligt uthängd. ”Jag lovar att inte visa klippet”, sa Leila. Mira ville tro henne. Ändå låg händelsen kvar som ett obehagligt minne.","Dagen före avslutningen kom en skärmbild från en gruppchatt hon inte var med i. Det stod: ”Mira kommer bli helt chockad när videon visas!” Mira drog genast slutsatsen att löftet var brutet. Hon skickade flera meddelanden till Leila, men inget svar kom. När Leila nästa dag frågade varför Mira undvek henne svarade hon kort: ”Du vet.” Det gjorde hon egentligen inte. Mira ville inte visa skärmbilden; hon var rädd att verka löjlig om hon hade missförstått.","På kvällen började en film med titeln ”Den som fick allt att fungera”. Den visade Mira när hon stannade kvar efter lektioner, hjälpte andra och lyckades få matteläraren att delta i ett humorinslag. Den pinsamma filmen fanns inte med. Leila hade planerat en uppskattning som Mira aldrig anat.","Efteråt förklarade Leila att hon inte vågat avslöja överraskningen och att hon läst meddelandena sent. Mira accepterade förklaringen, men deras samtal var inte helt färdigt. Hon tänkte på hur en sann skärmbild ändå hade lett henne till en felaktig slutsats. Samtidigt borde Leila ha förstått att tystnaden kunde uppfattas som ett svek."]}],"questions":[{"kind":"på raderna","ask":"Vad lovade Leila?","options":["Att inte visa det pinsamma klippet","Att ställa in avslutningen","Att aldrig använda mobilen"],"answer":0,"evidence":"Jag lovar att inte visa klippet","why":"Löftet gällde det pinsamma klippet, inte alla filmer."},{"kind":"mellan raderna","ask":"Varför blev Mira orolig av skärmbilden?","options":["Hon antog att filmen med hennes fall skulle visas","Hon hade glömt kvällens tid","Hon ville inte vara med på någon film"],"answer":0,"evidence":"Mira kommer bli helt chockad när videon visas!","why":"Mira kopplade en oklar kommentar till det hon redan var rädd för."},{"kind":"tolka","ask":"Vad gjorde missförståndet värre?","options":["Att ingen av dem förklarade situationen ordentligt","Att avslutningskvällen började för sent","Att det saknades musik"],"answer":0,"evidence":"Du vet.","why":"Det korta svaret förklarade inte vad Mira trodde hade hänt."}],"words":[{"term":"misstänka","explain":"tro att något kan ha hänt utan att veta säkert","example":"Mira misstänkte att löftet var brutet.","ask":"Hur skiljer sig misstanke från bevis?"},{"term":"hyllning","explain":"något som visar uppskattning för en person","example":"Filmen var en hyllning till Mira.","ask":"Hur kan man hylla någon utan att göra den obekväm?"},{"term":"slutsats","explain":"en tanke man kommer fram till utifrån information","example":"Hon drog en slutsats av skärmbilden.","ask":"Vad behövs för att en slutsats ska vara rimlig?"}],"blanks":[{"sentence":"Mira hade bara en skärmbild och drog därför en ___.","options":["slutsats","biljett","målning"],"answer":0,"why":"En slutsats är något vi kommer fram till utifrån information."},{"sentence":"Leila ville göra en ___ för Miras insats.","options":["hyllning","varning","försening"],"answer":0,"why":"Filmen visade uppskattning."},{"sentence":"Mira började ___ att löftet hade brutits.","options":["misstänka","räkna","viska"],"answer":0,"why":"Hon trodde något utan att veta det säkert."}],"retell":{"steps":["Vad hade hänt före skärmbilden?","Varför uppstod missförståndet?","Hur förändrades situationen på avslutningen?"],"model":"Mira var rädd att ett pinsamt klipp skulle visas. En skärmbild och obesvarade meddelanden fick henne att tro att Leila brutit sitt löfte. Filmen visade sig vara en hyllning, och vännerna behövde prata om sina antaganden."},"talk":{"prompt":"Var det främst Mira eller Leila som borde ha agerat annorlunda?","follow":"Vilken detalj i texten stödjer din åsikt? Kan din partner hitta ett motargument?","challenge":"Hitta en rimlig tolkning av Leilas tystnad som inte innebär svek."},"extra":{"2":{"kind":"mellan raderna","ask":"Vad hade Mira kunnat göra nästa dag för att minska risken för missförstånd?","options":["Visa skärmbilden och fråga direkt","Vänta tills flera andra spred ryktet","Låtsas att allting var bra"],"answer":0,"evidence":"Hon berättade inte vad hon misstänkte.","why":"Utan att berätta sin misstanke kunde Mira inte få ett tydligt svar."},"3":{"kind":"resonera","ask":"Vilken tolkning tar hänsyn till båda personernas ansvar?","options":["Mira antog för mycket, men Leilas tystnad bidrog till oron","Mira hade helt rätt och Leila ville henne illa","Ingen kunde påverka situationen"],"answer":0,"evidence":"tystnaden kunde uppfattas som ett svek","why":"Även goda avsikter kan skapa osäkerhet när kommunikationen brister."}}},{"id":"bibliotek","subject":"sv","genre":"Saktext","title":"Boken som redan var tillbaka","lead":"En till synes tråkig text där varje detalj kan spela roll.","levels":[{"level":1,"text":["På Björkbackaskolans bibliotek får man låna böcker i två veckor. Varje bok har en kod som registreras när någon lånar den. Om en elev vill låna längre går det ibland att förlänga lånet.","Det är inte alltid systemet visar det som nyss har hänt. En bok i återlämningslådan registreras först när personalen hunnit kontrollera den. Om en elev lämnar en bok på torsdag kan systemet fortfarande visa den som utlånad på fredag morgon.","Biblioteket har också en begränsad budget. Personalen vill köpa populära romaner, men måste även ha faktaböcker som behövs till skolarbetet. Därför kan en bok vara viktig även om nästan ingen lånar den."]},{"level":2,"text":["Skolbiblioteket registrerar varje lån med hjälp av en kod på boken och ett konto som hör till eleven. Den normala lånetiden är två veckor. En elev kan begära längre tid, men om någon annan väntar måste boken lämnas tillbaka som planerat.","Ett digitalt system gör det lättare att hålla ordning, men uppgifterna är inte alltid uppdaterade i samma stund som något händer. En bok i återlämningslådan registreras först när personalen hunnit kontrollera den. Den som lämnat tillbaka en bok på torsdag eftermiddag kan därför få en automatisk påminnelse på fredagen. Personalen ska kontrollera lådan och registreringen innan den drar slutsatser.","Biblioteket har en begränsad budget. Populära böcker kan ha väntelistor, medan vissa gamla faktaböcker sällan lånas. Ändå kan en ovanlig faktabok vara nödvändig för ett skolarbete. Personalen måste väga efterfrågan mot skolans uppdrag. Det finns inget enda tal i datorn som avgör vilka böcker som är värdefulla."]},{"level":3,"text":["På Björkbackaskolans bibliotek registreras varje utlån med en unik bokkod och elevens lånekonto. På så sätt kan personalen följa utlån, återlämningsdatum och efterfrågan. Den ordinarie lånetiden är två veckor, men förlängning kan medges om ingen annan väntar på boken. Systemet minskar det manuella arbetet men ersätter inte personalens bedömningar.","Det finns nämligen en tidsfördröjning mellan en fysisk återlämning och en digital registrering. En bok i återlämningslådan registreras först när personalen hunnit kontrollera den. Om boken läggs där strax före stängning på torsdagen kan systemet skicka en påminnelse på fredagsmorgonen. Påminnelsen visar då vad databasen innehåller, inte nödvändigtvis var boken faktiskt befinner sig. En rimlig rutin är därför att kontrollera lådan innan eleven får skulden för ett försenat lån.","Samma skillnad mellan mätning och verklighet påverkar inköpen. Biblioteket har en begränsad budget. Statistik visar vilka böcker som ofta lånas, men inte alla användningsområden. En faktabok om lokalhistoria kan vara efterfrågad bara under ett temaarbete vartannat år och ändå vara svår att ersätta. En populär roman kan samtidigt locka fler elever till regelbunden läsning.","Personalen väljer därför inte mellan ”populärt” och ”nyttigt” en gång för alla. Den behöver göra återkommande avvägningar mellan läslust, undervisning, kostnad och tillgänglighet. Underlaget från systemet är viktigt, men ofullständigt."]}],"questions":[{"kind":"på raderna","ask":"När registreras en bok som lagts i återlämningslådan?","options":["När personalen har kontrollerat den","Automatiskt när lådan stängs","Först efter två veckor"],"answer":0,"evidence":"registreras först när personalen hunnit kontrollera den","why":"Fysisk återlämning och digital registrering är inte alltid samma händelse."},{"kind":"mellan raderna","ask":"Varför kan en påminnelse skickas trots att eleven lämnat boken?","options":["Digital information kan vara försenad","Eleven kan inte läsa sin mejl","Biblioteket saknar böcker"],"answer":0,"evidence":"återlämningslådan","why":"Systemet kan visa det gamla läget fram till att personalen uppdaterar det."},{"kind":"tolka","ask":"Varför bör biblioteket inte bara köpa de mest utlånade böckerna?","options":["Ovanliga böcker kan fylla viktiga skolbehov","Alla populära böcker är dåliga","Ett bibliotek får inte låna ut romaner"],"answer":0,"evidence":"begränsad budget","why":"Beslut behöver ta hänsyn både till utlåningsstatistik och undervisningens behov."}],"words":[{"term":"registrera","explain":"föra in en uppgift i ett system","example":"Personalen måste registrera återlämningen.","ask":"Vad kan hända om uppgiften inte registreras direkt?"},{"term":"efterfrågan","explain":"hur många som vill ha något","example":"Efterfrågan är hög på en populär bok.","ask":"Kan en bok ha stort värde men låg efterfrågan?"},{"term":"avvägning","explain":"beslut där man tar hänsyn till flera olika behov","example":"Biblioteket gör en avvägning mellan kostnad och nytta.","ask":"Vilka två behov måste biblioteket väga mot varandra?"}],"blanks":[{"sentence":"När en bok kommer tillbaka måste den ___.","options":["registreras","förvandlas","förstoras"],"answer":0,"why":"Lånet ska markeras som återlämnat i systemet."},{"sentence":"En lång väntelista visar att ___ är stor.","options":["efterfrågan","höjden","längden"],"answer":0,"why":"Många vill låna just boken."},{"sentence":"Att välja mellan två viktiga behov kräver en ___.","options":["avvägning","gissning","ursäkt"],"answer":0,"why":"Flera intressen måste vägas mot varandra."}],"retell":{"steps":["Hur fungerar återlämningen?","Varför kan påminnelsen bli missvisande?","Hur väljer biblioteket nya böcker?"],"model":"Böcker registreras digitalt men återlämningar kan fördröjas innan de förs in. Därför kan en påminnelse vara fel. Biblioteket måste också väga populära titlar mot böcker som behövs för undervisningen."},"talk":{"prompt":"Ska biblioteket köpa fler populära böcker eller fler faktaböcker?","follow":"Använd minst ett argument från texten och hitta en rimlig kompromiss.","challenge":"Förklara med egna ord varför statistik inte alltid säger allt."},"extra":{"2":{"kind":"orsak och följd","ask":"Vad visar exemplet med fredagens påminnelse?","options":["Det digitala registret kan ligga efter den fysiska händelsen","Eleven har alltid glömt lämna tillbaka boken","Personalen ska aldrig registrera böcker"],"answer":0,"evidence":"automatisk påminnelse","why":"En automatisk påminnelse bygger på senast registrerad information."},"3":{"kind":"källkritik","ask":"Vilken slutsats stöds bäst av texten om bibliotekets statistik?","options":["Statistik är värdefull men behöver tolkas tillsammans med andra behov","Lånestatistik är alltid felaktig","En bok är värdelös om den lånas sällan"],"answer":0,"evidence":"Underlaget från systemet är viktigt, men ofullständigt","why":"Data visar vissa aspekter av verksamheten, inte allt värde."}}},{"id":"mobilregel","subject":"sv","genre":"Argumenterande","title":"Skolans nya mobilregel","lead":"Samma fråga – olika intressen.","levels":[{"level":1,"text":["Rektorn på en skola föreslog att mobiler skulle ligga i skåpen under lektionerna. Lärare tyckte att eleverna skulle få lättare att koncentrera sig. Flera elever höll med. Andra ville använda mobilen för att fotografera anteckningar eller kontakta familjen.","När regeln prövades blev några lektioner lugnare. Samtidigt blev vissa elever stressade när de inte snabbt kunde nå sina vårdnadshavare. Rektorn sa att skolan måste väga studiero mot tillgänglighet.","Efter samtal bestämde skolan att mobilerna fick användas under raster men inte under lektionerna, om inte läraren gav tillåtelse. Ingen fick exakt som den ville, men fler kunde acceptera regeln."]},{"level":2,"text":["På ett elevrådsmöte presenterade rektorn förslaget att alla mobiler skulle läggas undan under lektionerna. En del lärare menade att meddelanden och notiser avbröt arbetet. Vissa elever instämde: de tyckte det var lättare att koncentrera sig när ingen behövde kolla varje vibration. Andra påpekade att mobilen ibland användes för att fotografera genomgångar eller kontakta familjen.","Skolan testade regeln i två veckor. Flera lärare upplevde lugnare klassrum, men några elever beskrev oro över att inte kunna nå sina vårdnadshavare. Rektorn sa att skolan måste väga studiero mot tillgänglighet. Hon ville också veta om samma regel fungerade för alla elever.","Det slutliga beslutet blev att mobilerna normalt skulle ligga undan under lektionerna, med undantag när läraren bedömde att de behövdes. På rasterna fick eleverna använda dem. Det var inte en perfekt lösning för någon grupp, men det var en kompromiss som fler kunde leva med."]},{"level":3,"text":["När rektorn föreslog en strikt mobilregel beskrev hon den som en fråga om arbetsro. Meddelanden och sociala medier hade enligt flera lärare blivit återkommande avbrott. Några elever instämde. De märkte att de själva ibland tog upp mobilen utan att ha tänkt göra det.","Andra elever protesterade mot vad de uppfattade som ett alltför enkelt svar på ett komplicerat problem. För några var mobilen ett hjälpmedel för att fotografera anteckningar, hålla ordning på schemat eller kommunicera med familjen. Rektorn sa att skolan måste väga studiero mot tillgänglighet. Därför ville hon undersöka konsekvenserna i stället för att bara välja det förslag som lät tydligast.","Under en provperiod rapporterade lärare att vissa lektioner blev lugnare. Samtidigt kom signaler om att några elever kände stress när kontakten med familjen försvårades. Uppgifterna pekade åt olika håll: en åtgärd kunde förbättra ett mål samtidigt som ett annat försämrades.","Skolan beslutade att mobiler normalt skulle vara undanlagda under lektioner men fick användas på raster och vid undervisningsbehov. Dessutom skulle elever få veta hur de kunde nå familjen via skolans rutiner. Beslutet var en kompromiss, inte ett bevis för att alla problem var lösta.","En elev kommenterade: ”Regeln är inte min favorit, men åtminstone lyssnade de.” Hennes reaktion säger något om skillnaden mellan att hålla med om ett beslut och att uppleva att ens synpunkter har tagits på allvar."]}],"questions":[{"kind":"på raderna","ask":"Vad ville lärarna främst förbättra?","options":["Studieron under lektionerna","Skolans matsedel","Antalet raster"],"answer":0,"evidence":"studiero","why":"Lärarna ville minska avbrott under undervisningen."},{"kind":"mellan raderna","ask":"Varför var eleverna inte överens?","options":["Mobiler fyllde olika funktioner för olika elever","Ingen hade läst förslaget","Eleverna var inte intresserade av skolan"],"answer":0,"evidence":"familjen","why":"Det som stör en elev kan samtidigt vara ett hjälpmedel för en annan."},{"kind":"tolka","ask":"Vad visar rektorns beslut?","options":["Att flera behov ibland måste vägas mot varandra","Att elever alltid ska bestämma allt","Att mobiler aldrig kan vara användbara"],"answer":0,"evidence":"väga studiero mot tillgänglighet","why":"En kompromiss kan ta hänsyn till flera mål utan att helt uppfylla alla."}],"words":[{"term":"studiero","explain":"möjlighet att arbeta och koncentrera sig i lugn","example":"Studiero kan minska när notiser avbryter lektionen.","ask":"Vilka saker kan öka studieron?"},{"term":"tillgänglighet","explain":"hur lätt något eller någon går att nå eller använda","example":"Tillgänglighet kan handla om att kunna kontakta familjen.","ask":"Varför kan hög tillgänglighet ibland störa?"},{"term":"kompromiss","explain":"lösning där flera parter får ge upp något","example":"Mobilregeln blev en kompromiss.","ask":"När är en kompromiss bättre än att en part får allt?"}],"blanks":[{"sentence":"En lugn miljö kan bidra till bättre ___.","options":["studiero","väntelista","avresa"],"answer":0,"why":"Studiero handlar om att kunna arbeta i lugn."},{"sentence":"Möjligheten att nå sin familj handlar om ___.","options":["tillgänglighet","historik","matematik"],"answer":0,"why":"Tillgänglighet beskriver att något går att nå."},{"sentence":"Ett beslut där båda sidor ger med sig är en ___.","options":["kompromiss","katastrof","påminnelse"],"answer":0,"why":"Parterna får inte exakt som de ville."}],"retell":{"steps":["Vilket problem ville skolan lösa?","Vilka invändningar kom fram?","Vad blev beslutet och varför?"],"model":"Skolan ville förbättra studieron med mobilregler. Samtidigt behövde vissa elever mobilen för praktiska saker och familjekontakt. Rektorn valde en kompromiss med mobilfria lektioner och undantag när det behövdes."},"talk":{"prompt":"Skulle du införa samma mobilregel?","follow":"Ge ett argument för, ett argument emot och sedan ditt eget beslut.","challenge":"Vad skulle behöva mätas för att veta om regeln fungerade?"},"extra":{"2":{"kind":"motargument","ask":"Varför fick lärarna ibland göra undantag?","options":["Mobilen kunde behövas som hjälpmedel i undervisningen","Regeln gällde aldrig någon elev","Eleverna skulle tävla om flest notiser"],"answer":0,"evidence":"med undantag","why":"Det viktiga var användningen och sammanhanget, inte ett ovillkorligt förbud."},"3":{"kind":"resonera","ask":"Varför kan man acceptera en regel utan att tycka att den är perfekt?","options":["Man kan uppleva att ens synpunkter tagits på allvar","Man måste alltid hålla med rektorn","Alla regler fungerar lika för alla"],"answer":0,"evidence":"Regeln är inte min favorit, men åtminstone lyssnade de","why":"Delaktighet kan stärka acceptansen även när utfallet inte är ens förstahandsval."}}},{"id":"grupparbete","subject":"sv","genre":"Berättelse","title":"Vem gjorde egentligen arbetet?","lead":"Ett grupparbete, en tyst elev och en svår rättvisefråga.","levels":[{"level":1,"text":["I gruppen med fyra elever var det Alva som pratade mest. Hon fördelade uppgifter och höll presentationen. När läraren frågade vem som hade gjort arbetet svarade hon snabbt: ”Vi gjorde allt tillsammans.”","Samir sa nästan ingenting. Han hade hittat två viktiga källor och rättat flera fel, men ingen nämnde det. Alva såg att Samir tittade ner när klassen applåderade. Efteråt frågade hon varför han verkade missnöjd.","”Jag vill inte ta äran från någon”, sa Samir. ”Men jag vill att mitt arbete också ska märkas.” Alva insåg att den som pratar mest inte alltid har gjort mest. De bestämde att nästa gång skulle alla få berätta om sin del."]},{"level":2,"text":["Inför ett grupparbete delade Alva ut uppgifter, skapade en gemensam chatt och skrev talmanus. Hon var van att prata inför klassen och valdes därför till presentatör. Samir trivdes bättre med att läsa och kontrollera information. Han upptäckte att två av gruppens siffror var fel och letade upp bättre källor.","På presentationsdagen tog Alva nästan all talartid. När läraren frågade hur gruppen arbetat svarade hon: ”Vi gjorde allt tillsammans.” Det var inte helt fel, men Samir upplevde att orden suddade ut hans bidrag. Alva såg att Samir tittade ner när klassen applåderade, men hon visste inte varför.","Efteråt berättade Samir försiktigt hur han kände. Han ville inte ta äran från någon, bara få sitt eget arbete synligt. Alva insåg att den som pratar mest inte alltid har gjort mest. De kom överens om att nästa grupparbete skulle innehålla en kort redovisning av varje persons bidrag och att alla skulle få svara på en fråga."]},{"level":3,"text":["Gruppens uppgift var att undersöka hur elever reste till skolan. Alva tog snabbt rollen som samordnare: hon gjorde en plan, skrev i chatten, bokade ett klassrum och förberedde presentationen. De andra accepterade upplägget eftersom hon verkade säker och effektiv.","Samir ansvarade för att granska materialet. När han jämförde svaren upptäckte han att vissa elever hade räknats två gånger. Han rättade tabellen, letade upp kompletterande uppgifter och skrev en kort förklaring till varför gruppen behövde ändra slutsatsen. Hans arbete tog flera kvällar men syntes knappt på slutbilden.","Under redovisningen talade Alva nästan oavbrutet. När läraren frågade hur ansvaret fördelats svarade hon: ”Vi gjorde allt tillsammans.” Ingen invände. Alva såg att Samir tittade ner när klassen applåderade. Hon antog först att han bara var blyg.","Efteråt sade Samir att han uppskattade Alvas planering men att han inte ville bli osynlig. Han var noga med att inte påstå att hon inte hade arbetat. Alva insåg att den som pratar mest inte alltid har gjort mest. Hon hade inte avsiktligt tagit åt sig äran, men det förändrade inte hur situationen hade upplevts.","Gruppen föreslog en ny arbetsmetod: alla skulle dokumentera sina bidrag, byta roller ibland och få möjlighet att tala. Det skulle göra ansvaret tydligare utan att förvandla varje grupparbete till en tävling om beröm. Samir log när Alva bad honom förklara hur han hittat felen i tabellen."]}],"questions":[{"kind":"på raderna","ask":"Vad hade Samir bidragit med?","options":["Kontrollerat uppgifter och hittat fel","Bokat en konsertsal","Gjort skolans schema"],"answer":0,"evidence":"fel","why":"Samirs arbete var viktigt, även om han inte talade mest."},{"kind":"mellan raderna","ask":"Vad kan Samirs kroppsspråk antyda?","options":["Att han känner sig osynlig eller besviken","Att han glömt sin väska","Att han vill byta klass"],"answer":0,"evidence":"tittade ner","why":"Kroppsspråket tillsammans med det senare samtalet stöder tolkningen."},{"kind":"tolka","ask":"Vilken insikt får Alva?","options":["Den som pratar mest gör inte alltid mest","Det är bäst att aldrig göra grupparbeten","Tystnad betyder att alla är nöjda"],"answer":0,"evidence":"den som pratar mest inte alltid har gjort mest","why":"Synliga insatser och tysta bidrag kan båda vara viktiga."}],"words":[{"term":"bidrag","explain":"en del av det arbete eller den hjälp någon ger","example":"Samirs bidrag till gruppen var betydelsefullt.","ask":"Vilka olika bidrag kan man göra i en grupp?"},{"term":"ansvar","explain":"det man har skyldighet att ta hand om","example":"Varje elev fick ansvar för en del.","ask":"Hur märks det att man tar ansvar?"},{"term":"synlig","explain":"något som märks eller går att se","example":"Hans arbete var viktigt men inte synligt.","ask":"Kan något vara viktigt utan att vara synligt?"}],"blanks":[{"sentence":"Samir ville att hans ___ skulle uppmärksammas.","options":["bidrag","nummer","frukost"],"answer":0,"why":"Det handlade om den del han gjort."},{"sentence":"Gruppen behövde fördela sitt ___.","options":["ansvar","väder","jubel"],"answer":0,"why":"Alla behövde veta vilka uppgifter de skulle göra."},{"sentence":"Ett arbete kan vara viktigt fast det inte är ___.","options":["synligt","farligt","runt"],"answer":0,"why":"Man kan bidra mycket utan att tala högt."}],"retell":{"steps":["Hur fördelades uppgifterna?","Varför var Samir besviken?","Vad ändrade gruppen till nästa gång?"],"model":"Alva organiserade och presenterade, medan Samir bland annat granskade materialet. Samir upplevde att hans bidrag inte syntes. Efter ett samtal bestämde gruppen att göra ansvar och insatser tydligare för alla."},"talk":{"prompt":"Vad är mest rättvist: lika mycket talartid eller att alla bidrag erkänns?","follow":"Försök ge två olika rimliga svar och visa textstöd.","challenge":"Hur kan man känna igen arbete som är svårt att se?"},"extra":{"2":{"kind":"tolka","ask":"Varför kunde Alvas svar vara missvisande utan att vara helt falskt?","options":["Gruppen samarbetade, men deras olika bidrag syntes inte","Samir hade inte arbetat alls","Läraren ville bara ha ett ja eller nej"],"answer":0,"evidence":"Det var inte helt fel","why":"Att säga att man gjorde allt tillsammans kan dölja ojämn synlighet."},"3":{"kind":"nyanser","ask":"Vad visar texten om avsikt och konsekvens?","options":["Att man kan såra någon utan att ha menat det","Att varje misstag är medvetet","Att tysta personer inte vill delta"],"answer":0,"evidence":"Hon hade inte avsiktligt tagit åt sig äran","why":"Avsikten var inte elak men effekten blev ändå att Samirs arbete osynliggjordes."}}},{"id":"screenshot","subject":"en","genre":"Story","title":"The message in the class chat","lead":"A surprise, an unanswered message and an assumption.","levels":[{"level":1,"text":["Aisha and Zoe were preparing a school event. One day Aisha slipped during a rehearsal, and someone recorded it. She laughed with her friends but did not want the clip online. “I promise I will not post it,” Zoe said.","The next afternoon, Aisha saw a screenshot from a class chat: “Wait until Aisha sees the video!” She sent Zoe a message, but Zoe did not answer. Aisha believed Zoe had broken her promise.","At the event, a video showed Aisha helping classmates and making everyone laugh. The embarrassing clip was not there. It was a thank-you video. Aisha felt relieved, but she wished she had asked Zoe what was happening."]},{"level":2,"text":["Aisha spent several afternoons helping Zoe prepare the school's celebration. During a rehearsal, Aisha fell over a chair. Everyone laughed, including Aisha, but later she felt embarrassed when she watched the recording. “I promise I will not post it,” Zoe said.","On Thursday Aisha received a screenshot from another class chat. It said: “Wait until Aisha sees the video!” She immediately thought of the accident. Zoe did not answer her messages, so Aisha decided that her friend had broken the promise. When Zoe tried to talk at school, Aisha walked away instead of explaining.","That evening a short film played on the screen. It showed Aisha helping other students, organising decorations and making people smile. The embarrassing clip was not there. Zoe had planned a surprise to thank her. Aisha was relieved, but she also realised that she had treated one possible explanation as the only explanation."]},{"level":3,"text":["Aisha was used to being the person who kept school projects organised. She prepared schedules, checked everyone’s ideas and stayed late when tasks were unfinished. Yet she was unusually nervous about the end-of-term celebration.","During an earlier rehearsal, Aisha had slipped on a chair in front of a camera. Laughing at the accident had been easy in the moment; seeing it replayed later was different. She felt exposed. Zoe noticed and said, “I promise I will not post it.” Aisha wanted to trust her.","The day before the event, someone sent Aisha a screenshot from a group chat she did not belong to. It said: “Wait until Aisha sees the video!” Aisha immediately connected that message to the embarrassing clip. Zoe was busy preparing a surprise and did not answer her phone. Silence seemed to confirm Aisha's fear, although it actually gave her no new facts.","At the celebration, the screen showed a video about Aisha's work for the class. Her classmates thanked her for helping them. The embarrassing clip was not there. Zoe's surprise was kind, but the earlier silence had caused real worry.","Later, Aisha admitted that she had drawn a conclusion before asking a clear question. Zoe agreed that she should have responded sooner. They realised that a screenshot can be genuine while the meaning someone gives it is still mistaken."]}],"questions":[{"kind":"literal","ask":"What did Zoe promise?","options":["Not to post the embarrassing video","To cancel the school celebration","To delete all school photos"],"answer":0,"evidence":"I promise I will not post it","why":"The promise was about the embarrassing clip."},{"kind":"inference","ask":"Why was Aisha upset by the screenshot?","options":["She connected it to the clip of her fall","She wanted to record another video","She disliked the school decorations"],"answer":0,"evidence":"Wait until Aisha sees the video!","why":"The message was unclear; Aisha assumed the worst."},{"kind":"interpretation","ask":"What is the main lesson?","options":["Check an assumption before treating it as a fact","Never trust any screenshot","School celebrations should not include videos"],"answer":0,"evidence":"embarrassing clip was not there","why":"A genuine message can still be misunderstood."}],"words":[{"term":"assumption","explain":"something you think is true without enough proof","example":"Aisha made an assumption about the video.","ask":"How can you test an assumption?"},{"term":"relieved","explain":"feeling better because a worry has ended","example":"Aisha felt relieved when she saw the film.","ask":"When have you felt relieved?"},{"term":"promise","explain":"a statement that you will or will not do something","example":"Zoe made a promise about the video.","ask":"Why do promises matter in friendships?"}],"blanks":[{"sentence":"Aisha was ___ when she discovered the clip was not shown.","options":["relieved","careless","invisible"],"answer":0,"why":"A worry disappeared."},{"sentence":"She had made an ___ without checking the facts.","options":["assumption","appointment","agreement"],"answer":0,"why":"She believed something before she knew."},{"sentence":"Zoe wanted to keep her ___.","options":["promise","receipt","ticket"],"answer":0,"why":"She said she would not post the clip."}],"retell":{"steps":["What was Aisha afraid of?","What did the screenshot make her think?","What happened at the event and afterwards?"],"model":"Aisha feared that her embarrassing video would be shown. A screenshot and unanswered messages made her doubt Zoe. The video was actually a surprise to thank her, so they talked about assumptions and communication."},"talk":{"prompt":"Who could have communicated better, and how?","follow":"Give one clue from the story and ask your partner for a different explanation.","challenge":"Explain how a true message can still create a false conclusion."},"extra":{"2":{"kind":"inference","ask":"Which action might have prevented the misunderstanding?","options":["Aisha explaining what she had seen to Zoe","Aisha sharing the screenshot with everyone","Zoe cancelling the entire celebration"],"answer":0,"evidence":"instead of explaining","why":"A direct question could have tested the assumption."},"3":{"kind":"interpretation","ask":"What does the sentence about silence suggest?","options":["Silence can feel like evidence even when it proves nothing","Silence always means betrayal","A message cannot be misunderstood"],"answer":0,"evidence":"no new facts","why":"The lack of a reply did not actually show what the video contained."}}},{"id":"library","subject":"en","genre":"Information","title":"The book that was already returned","lead":"A boring-sounding system with a surprising problem.","levels":[{"level":1,"text":["The school library lends books for two weeks. Every book has a code, so staff can see who borrowed it. Students can sometimes extend a loan if nobody else is waiting.","A returned book is only recorded after a staff member checks the return box. This means the computer may still show a book as borrowed even after a student has brought it back. The student might receive an automatic reminder.","The library has a limited budget. Staff buy popular stories, but they also need books for school projects. A book can be useful even if very few students borrow it."]},{"level":2,"text":["At Hillview School Library, every book has a code linked to a student's account. The normal loan period is two weeks. Students can ask to keep a book longer, but they cannot always do so if somebody else is waiting.","The computer makes loans easier to track, yet its information is not always completely up to date. A returned book is only recorded after a staff member checks the return box. A student who returns a book late on Thursday may still receive a reminder on Friday morning. The system is reporting an old record, not necessarily the student's behaviour.","Money creates another difficult decision. The library has a limited budget. Popular novels may have long waiting lists while some reference books are rarely borrowed. Still, an unusual book may be essential for a particular history assignment. Staff must consider both popularity and educational value."]},{"level":3,"text":["The library at Hillview School uses electronic records to manage loans. Each item is identified by a code, and the system stores who borrowed it and when it should be returned. Students can request an extension, unless another borrower is waiting.","Although a database seems precise, there can be a delay between events in the real world and changes to the record. A returned book is only recorded after a staff member checks the return box. A student may put a book into the box on Thursday afternoon and receive an automated reminder on Friday. The reminder is generated from information that has not yet been updated. It does not automatically prove the student has acted irresponsibly.","A similar problem appears when staff decide which books to buy. The library has a limited budget. Borrowing figures tell staff which books are popular, but they do not fully measure educational value. A detailed local-history book might only be used during one project every two years, yet be difficult to replace. A popular novel might encourage a reluctant reader to read regularly.","The best decision is therefore not simply to buy the most borrowed books or to keep every old book forever. The library needs a process that considers demand, the curriculum, costs and how difficult each resource is to replace."]}],"questions":[{"kind":"literal","ask":"When is a returned book registered?","options":["After staff check the return box","As soon as the school bell rings","Only at the end of the year"],"answer":0,"evidence":"staff member checks the return box","why":"The physical return happens before the record is updated."},{"kind":"inference","ask":"Why might a student receive an incorrect reminder?","options":["The digital record may not yet be updated","The student must pay to read","The library never accepts returns"],"answer":0,"evidence":"returned book","why":"An automatic reminder can rely on old information."},{"kind":"interpretation","ask":"Why is borrowing data not enough to choose new books?","options":["Some rarely borrowed books still support schoolwork","Popular books are never useful","Only old books can be accurate"],"answer":0,"evidence":"limited budget","why":"Library value includes educational needs, not just popularity."}],"words":[{"term":"reminder","explain":"a message that tells you to do something","example":"The system sent a reminder about the loan.","ask":"What would you do if a reminder was incorrect?"},{"term":"demand","explain":"how many people want something","example":"Demand for the new novel was high.","ask":"Can demand be low while value is high?"},{"term":"reliable","explain":"likely to be correct and trusted","example":"A reliable record should be updated.","ask":"What makes information reliable?"}],"blanks":[{"sentence":"The computer sent an automatic ___.","options":["reminder","holiday","novel"],"answer":0,"why":"It sent a message about returning the book."},{"sentence":"There was high ___ for a popular novel.","options":["demand","weather","silence"],"answer":0,"why":"Many students wanted the same book."},{"sentence":"The library needs ___ information before accusing anyone.","options":["reliable","noisy","fictional"],"answer":0,"why":"It needs information it can trust."}],"retell":{"steps":["How are books recorded?","Why can an automatic message be wrong?","How does the library choose books to buy?"],"model":"The library records loans electronically, but returns may be updated later. This can cause incorrect reminders. Staff also decide how to spend a small budget, balancing popular stories with books needed for learning."},"talk":{"prompt":"Should a school library buy more popular novels or more reference books?","follow":"Give two arguments and agree on one compromise.","challenge":"Explain the difference between a record and what has really happened."},"extra":{"2":{"kind":"cause and effect","ask":"Why can a reminder be inaccurate on Friday?","options":["The record may not reflect a Thursday return yet","The staff always deletes the record","Books can never be returned on Thursday"],"answer":0,"evidence":"old record","why":"The system can have outdated information."},"3":{"kind":"evaluation","ask":"What is a more careful way to choose library books?","options":["Consider popularity, learning needs and replacement difficulty","Buy only books with the most loans","Never buy new books"],"answer":0,"evidence":"how difficult each resource is to replace","why":"The best choice weighs several types of value."}}},{"id":"homework","subject":"en","genre":"Argument","title":"Should homework be flexible?","lead":"Two students disagree without either being foolish.","levels":[{"level":1,"text":["Some students want teachers to give less homework. They say they need time to rest, exercise and help at home. Other students think homework helps them practise what they learned in class.","The student council suggested that pupils should be able to choose between two tasks that practise the same skill. The school wanted to balance practice and free time.","One teacher liked the idea but worried that some choices would be too easy. Another teacher suggested a short review in class to make sure everyone learned something. The council decided to test the idea before asking the school to change its rules."]},{"level":2,"text":["At a student council meeting, several pupils argued that homework should be more flexible. Some said that long assignments were difficult to combine with sports, family responsibilities and rest. Others argued that practice outside school could help students remember what they had learned.","Instead of asking for all homework to disappear, the council suggested a choice of two tasks covering the same skill. The school wanted to balance practice and free time. One option might be to write a short explanation; another might be to record a spoken explanation. Both would need to show understanding.","A teacher warned that students might always pick the easiest option. Another suggested that teachers should check the results through a short question in class. The students agreed that the plan needed a trial rather than an immediate permanent rule. A compromise could be successful without satisfying everyone's first request."]},{"level":3,"text":["At Hillview School, homework had become a regular source of disagreement. Some families argued that repeated long assignments left too little time for sport, rest and responsibilities at home. Others felt that independent practice was necessary, particularly when pupils needed to remember vocabulary or mathematics methods.","The student council tried to move beyond a simple argument about whether homework was good or bad. It proposed offering two different ways to practise the same skill. A student might prepare a spoken explanation or a short written one, for example. The school wanted to balance practice and free time. Supporters believed that having a choice could make tasks feel more manageable.","Teachers raised practical questions. How could they know whether the two options were equally demanding? Would pupils choose activities based on what helped them learn, or simply what took the least effort? How could a student without a quiet space at home complete an assignment fairly?","The council suggested a limited trial. Teachers would set a clear learning goal, offer two routes to that goal and check understanding briefly in the following lesson. The school would compare the quality of answers and pupils' experiences before making a decision.","The disagreement was not completely resolved. However, the debate had changed: instead of arguing about whether students deserved less work, participants were discussing how to make practice useful, fair and achievable."]}],"questions":[{"kind":"literal","ask":"What did the student council propose?","options":["A choice between two ways to practise the same skill","No schoolwork of any kind","One long exam every evening"],"answer":0,"evidence":"same skill","why":"The tasks would differ in form but practise the same goal."},{"kind":"inference","ask":"Why were some teachers worried?","options":["Students might choose the easiest task rather than a useful one","They disliked all student opinions","They wanted to cancel every subject"],"answer":0,"evidence":"practice and free time","why":"The school needed to keep learning goals while giving flexibility."},{"kind":"interpretation","ask":"What is the most reasonable conclusion?","options":["Test choices while checking what students learn","Homework is always harmful","Students should always decide grades"],"answer":0,"evidence":"balance practice and free time","why":"The text presents competing needs, not one simple winner."}],"words":[{"term":"flexible","explain":"able to change or adapt to different needs","example":"A flexible plan may offer two options.","ask":"How can a school task be flexible without becoming easier?"},{"term":"objective","explain":"a goal you want to reach","example":"The objective was to practise the same skill.","ask":"Give an objective for learning new vocabulary."},{"term":"trial","explain":"a test before deciding permanently","example":"The council asked for a short trial.","ask":"What would you measure during a trial?"}],"blanks":[{"sentence":"A ___ schedule can change when needed.","options":["flexible","invisible","noisy"],"answer":0,"why":"It can adapt to different circumstances."},{"sentence":"A clear learning ___ helps students know what to practise.","options":["objective","accident","rumour"],"answer":0,"why":"It is a goal."},{"sentence":"Before changing the rules, they wanted to run a ___.","options":["trial","party","concert"],"answer":0,"why":"It would test the idea first."}],"retell":{"steps":["Why was homework debated?","What alternative did students propose?","What would a fair test of the idea require?"],"model":"Some students wanted more free time, while others valued practice. The council suggested choosing between two ways to practise the same skill. Teachers wanted to test the idea and check that pupils still learned."},"talk":{"prompt":"Should homework be shorter, more flexible, or unchanged?","follow":"Use the text to support your view and challenge one argument politely.","challenge":"What evidence would make you change your opinion?"},"extra":{"2":{"kind":"inference","ask":"What would make the new homework choices fairer?","options":["Check learning goals in class after either task","Allow only one student to choose","Remove all learning goals"],"answer":0,"evidence":"short question in class","why":"Teachers could test understanding regardless of which task was chosen."},"3":{"kind":"evaluation","ask":"How did the council improve the debate?","options":["It turned a yes-or-no argument into a discussion of useful practice","It proved homework is never needed","It made all students agree immediately"],"answer":0,"evidence":"the debate had changed","why":"A better question concerns how learning can be effective and achievable."}}},{"id":"trophy","subject":"en","genre":"Story","title":"The missing team trophy","lead":"A mystery that was solved by asking a better question.","levels":[{"level":1,"text":["After the school sports day, the team trophy disappeared. Ben saw Nora leave the hall with a large bag. He decided she had taken it and told two friends.","Nora was upset when she heard the rumour. “I was carrying the team shirts,” she said. Ben realised he had only seen a bag, not the trophy.","Later, the caretaker found the trophy in the equipment cupboard. It had been moved for cleaning. Ben apologised, and Nora asked him to check facts before talking about someone. The team learned that being certain is not the same as being correct."]},{"level":2,"text":["The morning after sports day, the football trophy was missing from the school hall. Ben remembered seeing Nora carry a large sports bag out of the building. He told two friends that she had probably taken the trophy. By lunchtime, several classmates had heard the story.","Nora was hurt because Ben had never asked her what was in the bag. “I was carrying the team shirts,” she explained. Ben realised he had only seen a bag, not the trophy. He had treated one possible explanation as a fact.","The caretaker eventually found the trophy in the equipment cupboard, where it had been moved while the hall was cleaned. Ben apologised to Nora and corrected the rumour in the class chat. She accepted the apology, but she said that the story had been embarrassing even after people learned the truth. The team learned that being certain is not the same as being correct."]},{"level":3,"text":["On Monday morning, the winning team's trophy was missing from the display table in the school hall. Ben was convinced that someone had taken it. He remembered seeing Nora leave the building after the sports day with a large bag, and the memory suddenly seemed suspicious.","Instead of speaking to Nora, he told two teammates she had probably taken the trophy. The story spread quickly through a group chat. By the time Nora heard it, the word “probably” had disappeared; several students were repeating the accusation as a fact.","“I was carrying the team shirts,” Nora explained, visibly upset. Ben realised he had only seen a bag, not the trophy. His observation was real, but his conclusion went beyond it. He had also overlooked a simpler possibility: that the trophy had been moved by someone responsible for the hall.","Later that day, the caretaker found the trophy in the equipment cupboard. It had been stored there while the hall was cleaned. Ben wrote a message correcting the rumour and apologised to Nora in person.","Nora did not pretend that the apology instantly erased the embarrassment. She appreciated that he corrected his mistake, but she asked him to speak more carefully next time. The team learned that being certain is not the same as being correct, especially when an accusation can damage someone's reputation."]}],"questions":[{"kind":"literal","ask":"What was Nora actually carrying?","options":["The team shirts","The missing trophy","A box of medals"],"answer":0,"evidence":"team shirts","why":"She had a harmless reason for the bag."},{"kind":"inference","ask":"What was Ben’s main mistake?","options":["Treating a guess as if it were proof","Asking Nora too many questions","Checking the cupboard first"],"answer":0,"evidence":"only seen a bag, not the trophy","why":"Seeing the bag did not prove what was inside."},{"kind":"interpretation","ask":"What lesson does the team learn?","options":["Confidence does not guarantee accuracy","You should never apologise","Rumours are always true"],"answer":0,"evidence":"being certain is not the same as being correct","why":"A confident belief can still be mistaken."}],"words":[{"term":"rumour","explain":"a story that spreads without being confirmed","example":"A rumour spread around the class.","ask":"What can a rumour do to someone’s reputation?"},{"term":"accuse","explain":"to say that someone has done something wrong","example":"Ben accused Nora without proof.","ask":"What should you check before accusing someone?"},{"term":"apologise","explain":"to say sorry for something you did","example":"Ben chose to apologise to Nora.","ask":"How can you show that an apology is sincere?"}],"blanks":[{"sentence":"An unconfirmed story spreading through school is a ___.","options":["rumour","schedule","solution"],"answer":0,"why":"It was not based on confirmed information."},{"sentence":"You should not ___ someone without evidence.","options":["accuse","explain","include"],"answer":0,"why":"It means claiming that somebody did something wrong."},{"sentence":"Ben needed to ___ after the mistake.","options":["apologise","celebrate","disappear"],"answer":0,"why":"He needed to say sorry."}],"retell":{"steps":["What disappeared and who was blamed?","Which clue was misunderstood?","How was the truth discovered and the harm addressed?"],"model":"A trophy went missing and Ben suspected Nora because she carried a large bag. It only contained shirts. The caretaker found the trophy in a cupboard, and Ben apologised and corrected the rumour."},"talk":{"prompt":"Was correcting the group chat enough, or should Ben do more?","follow":"Give reasons and compare your view with your partner’s.","challenge":"What is the difference between an observation and an accusation?"},"extra":{"2":{"kind":"inference","ask":"Why was fixing the rumour still important after the trophy was found?","options":["Other students had heard the incorrect story about Nora","Nobody had ever heard the story","Nora asked for another trophy"],"answer":0,"evidence":"corrected the rumour","why":"An apology alone might not correct what other people believe."},"3":{"kind":"interpretation","ask":"What changed as the rumour spread?","options":["A possibility was repeated as a definite accusation","People began to ask more careful questions","The caretaker confirmed Ben was right"],"answer":0,"evidence":"the word “probably” had disappeared","why":"Uncertain information became falsely presented as certain."}}}];});
